def compile : RawDirectMeasureShape → SemanticMeasureData (Nat × Nat)
  | .counterProjection =>
      { A := Nat, ltA := (· < ·), wf_ltA := Nat.lt_wfRel.wf,
        μ := fun p => p.fst }
  | .payloadProjection =>
      { A := Nat, ltA := (· < ·), wf_ltA := Nat.lt_wfRel.wf,
        μ := fun p => p.snd }
  | .constantMeasure a =>
      { A := Nat, ltA := (· < ·), wf_ltA := Nat.lt_wfRel.wf,
        μ := fun _ => a }
  | .counterPlusPayload =>
      { A := Nat, ltA := (· < ·), wf_ltA := Nat.lt_wfRel.wf,
        μ := fun p => p.fst + p.snd }
  | .payloadPlusConst k =>
      { A := Nat, ltA := (· < ·), wf_ltA := Nat.lt_wfRel.wf,
        μ := fun p => p.snd + k }

